from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')

print("=== Verification of Processed PowerPoint ===\n")

for slide_idx, slide in enumerate(prs.slides):
    print(f"--- Slide {slide_idx + 1} ---")
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TEXT_BOX:
            if hasattr(shape, "text") and shape.text.strip():
                print(f"  Text Box: '{shape.text[:60]}...'")
                print(f"    Position: left={shape.left.inches:.2f}, top={shape.top.inches:.2f}")
                print(f"    Size: width={shape.width.inches:.2f}, height={shape.height.inches:.2f}")

                # Check formatting
                if shape.has_text_frame:
                    for para in shape.text_frame.paragraphs:
                        print(f"    Alignment: {para.alignment}")
                        for run in para.runs:
                            print(f"    Font: name={run.font.name}, size={run.font.size}, bold={run.font.bold}")
                            if run.font.color.rgb:
                                print(f"    Color: #{run.font.color.rgb}")
    print()

# Verify reference slide
print("=== Reference Slide Content ===")
ref_slide = prs.slides[-1]
for shape in ref_slide.shapes:
    if hasattr(shape, "text") and shape.text.strip():
        print(f"Shape: {shape.name}")
        print(f"  Text preview: {shape.text[:200]}...")
        print()
EOF
